export const NAMED_PLAYER_KEYS = Object.keys(NAMED_PLAYERS);

// ── Helper: retorna URL da foto de um jogador (fonte única) ────────
// Funciona com objeto player em runtime OU com namedPlayerKey/name como strings.
// Prioridade: player.photo → NAMED_PLAYERS[key].photo → null
export function getPlayerPhoto(playerOrKey) {
  if (!playerOrKey) return null;
  // Já é um objeto player com foto embutida
  if (typeof playerOrKey === 'object' && playerOrKey.photo) return playerOrKey.photo;
  // É um objeto player com namedPlayerKey
  if (typeof playerOrKey === 'object' && playerOrKey.namedPlayerKey) {
    const np = NAMED_PLAYERS[playerOrKey.namedPlayerKey];
    if (np?.photo) return np.photo;
  }
  // É uma string (namedPlayerKey ou id)
  if (typeof playerOrKey === 'string') {
    const np = NAMED_PLAYERS[playerOrKey.toUpperCase()];
    if (np?.photo) return np.photo;
  }
  return null;
}

// ── Inicializar DNA traits nos jogadores nomeados ──────────────────
import { applyPlayerTraits } from './PlayerTraits.js';

// ── Auto-migração v3: converte attrs antigos (28) para novos (14) ──
// Qualquer jogador que ainda usa o sistema antigo é migrado automaticamente.
// Todos os jogadores agora usam schema v3 nativo (14 atributos).
// Migração permanente aplicada em março/2026 — não há mais schema antigo.

applyPlayerTraits(NAMED_PLAYERS);
